cd /app && cat > internal/cache/redis/client.go <<'EOF'
package redis

import (
	"crypto/tls"
	"crypto/x509"
	"fmt"
	"os"

	goredis "github.com/redis/go-redis/v9"
	"go.flipt.io/flipt/internal/config"
)

// NewClient constructs a redis client from the provided configuration.
//
// When TLS is requested (require_tls) the client negotiates a connection with a
// minimum of TLS 1.2 and trusts, in order of precedence:
//
//   - an inline certificate authority bundle (ca_cert_bytes)
//   - a certificate authority bundle read from disk (ca_cert_path)
//   - the system certificate pool, when neither of the above are supplied
//
// Certificate verification can be disabled entirely via insecure_skip_tls.
func NewClient(cfg config.RedisCacheConfig) (*goredis.Client, error) {
	var tlsConfig *tls.Config
	if cfg.RequireTLS {
		tlsConfig = &tls.Config{
			MinVersion: tls.VersionTLS12,
		}

		tlsConfig.InsecureSkipVerify = cfg.InsecureSkipTLS

		caBundle, err := caBundle(cfg)
		if err != nil {
			return nil, err
		}

		// when no custom certificate authority is supplied we leave RootCAs
		// unset, which defers trust to the systems certificate pool
		if len(caBundle) > 0 {
			rootCAs, err := x509.SystemCertPool()
			if err != nil {
				return nil, err
			}

			rootCAs.AppendCertsFromPEM(caBundle)
			tlsConfig.RootCAs = rootCAs
		}
	}

	rdb := goredis.NewClient(&goredis.Options{
		Addr:            fmt.Sprintf("%s:%d", cfg.Host, cfg.Port),
		TLSConfig:       tlsConfig,
		Username:        cfg.Username,
		Password:        cfg.Password,
		DB:              cfg.DB,
		PoolSize:        cfg.PoolSize,
		MinIdleConns:    cfg.MinIdleConn,
		ConnMaxIdleTime: cfg.ConnMaxIdleTime,
		DialTimeout:     cfg.NetTimeout,
		ReadTimeout:     cfg.NetTimeout * 2,
		WriteTimeout:    cfg.NetTimeout * 2,
		PoolTimeout:     cfg.NetTimeout * 2,
	})

	return rdb, nil
}

// caBundle resolves the certificate authority bundle to trust for TLS
// connections. It prefers inline configuration over a path on disk and
// returns an empty bundle when neither has been configured.
func caBundle(cfg config.RedisCacheConfig) ([]byte, error) {
	if cfg.CaCertBytes != "" {
		return []byte(cfg.CaCertBytes), nil
	}

	if cfg.CaCertPath != "" {
		return os.ReadFile(cfg.CaCertPath)
	}

	return []byte{}, nil
}
EOF
